package runid
import("crypto/sha256";"encoding/hex";"encoding/json";"fmt";"github.com/LuigiD5555/origami/internal/lab/canonical";"github.com/LuigiD5555/origami/internal/lab/spec")
const MaterializationSchemaV1="ohf.materialization-identity.v1"
type MaterializationIdentity struct{Schema string `json:"schema"`;ExperimentSpecSHA256 string `json:"experiment_spec_sha256"`;SourceSHA256 string `json:"source_sha256"`;RendererID string `json:"renderer_id"`;RendererVersion string `json:"renderer_version"`;RendererBinarySHA256 string `json:"renderer_binary_sha256,omitempty"`;ProtocolVersion string `json:"protocol_version"`;BaselineVersion string `json:"baseline_version"`}
func ExperimentID(s spec.ExperimentSpec)(string,string,error){h,err:=canonical.SpecHash(s);if err!=nil{return "","",err};return short(h)}
func RunID(identity MaterializationIdentity)(string,string,error){if identity.Schema!=MaterializationSchemaV1{return "","",fmt.Errorf("run id: unexpected schema %q",identity.Schema)};if identity.ExperimentSpecSHA256==""||identity.SourceSHA256==""||identity.RendererID==""||identity.RendererVersion==""||identity.ProtocolVersion==""||identity.BaselineVersion==""{return "","",fmt.Errorf("run id: incomplete materialization identity")};b,err:=json.Marshal(identity);if err!=nil{return "","",err};sum:=sha256.Sum256(b);return short(hex.EncodeToString(sum[:]))};func short(h string)(string,string,error){if len(h)<16{return "","",fmt.Errorf("unexpected hash length")};return h[:16],h,nil}
